from collections import Counter

from fastapi import FastAPI, Request
from fastapi.responses import PlainTextResponse

app = FastAPI()

# (path, status) -> count
REQUEST_COUNTS: Counter[tuple[str, str]] = Counter()


@app.middleware("http")
async def count_requests(request: Request, call_next):
    response = await call_next(request)
    path = request.scope.get("route").path if "route" in request.scope else request.url.path
    if path != "/metrics":
        REQUEST_COUNTS[(path, str(response.status_code))] += 1
    return response


@app.get("/metrics", response_class=PlainTextResponse)
async def metrics():
    lines = [
        f'http_requests_total{{path="{path}",status="{status}"}} {count}'
        for (path, status), count in sorted(REQUEST_COUNTS.items())
    ]
    return "\n".join(lines) + ("\n" if lines else "")


@app.get("/items")
async def items():
    return {"items": []}


@app.get("/health")
async def health():
    return {"ok": True}

